insert into public.prompts (id, author_id, title, description, prompt_text, tool, content_type, status, origin_type, request_id, created_at, updated_at) values ('5eed0001-0000-4000-8000-000000000005', '5eed0000-0000-4000-8000-000000000001', 'Siberpunk Hikaye Açılışı Promptu', 'Hikaye yazarken ilk paragrafı ChatGPT''ye böyle yazdırıyorum, sonrasını ben devam ettiriyorum.', 'Write the opening paragraph of a cyberpunk noir short story set in a rainy, overpopulated future Istanbul. The narrator is a burned-out memory broker. Use sensory details (smell, sound, light), short punchy sentences and end with a hook that introduces a mysterious client. Max 150 words.', 'ChatGPT', 'text', 'published', 'original', null, '2026-08-07T13:07:12.724Z', '2026-08-07T13:07:12.724Z');
