insert into public.prompts (id, author_id, title, description, prompt_text, tool, content_type, status, origin_type, request_id, created_at, updated_at) values ('5eed0001-0000-4000-8000-000000000006', '5eed0000-0000-4000-8000-000000000002', 'Kod İnceleme Asistanı', 'PR açmadan önce kendi kodumu bu promptla inceletiyorum. Güvenlik açıklarını gerçekten yakalıyor.', 'You are a senior software engineer doing a strict code review. Review the following diff for: (1) correctness bugs, (2) security issues (injection, auth, secrets), (3) performance problems, (4) readability. For each finding give: severity, file:line, why it is a problem, and a concrete fix as a code snippet. Do not comment on formatting. If everything is fine, say so explicitly.
