insert into public.prompts (id, author_id, title, description, prompt_text, tool, content_type, status, origin_type, request_id, created_at, updated_at) values ('5eed0001-0000-4000-8000-000000000007', '5eed0000-0000-4000-8000-000000000002', 'SQL Sorgu Optimizasyonu', 'Yavaş çalışan Postgres sorgularımı buna veriyorum, EXPLAIN çıktısıyla birlikte.', 'Act as a PostgreSQL performance expert. Given the query and its EXPLAIN ANALYZE output below, identify the bottleneck, explain it in plain language, and propose (a) a rewritten query and (b) any indexes to add with the exact CREATE INDEX statement. Mention trade-offs.
