insert into public.prompts (id, author_id, title, description, prompt_text, tool, content_type, status, origin_type, request_id, created_at, updated_at) values ('5eed0001-0000-4000-8000-000000000008', '5eed0000-0000-4000-8000-000000000002', 'Birim Testi Yazdırma', 'Jest ile test yazmaktan sıkılınca bunu kullanıyorum. Edge case''leri gerçekten düşünüyor.', 'Write Jest unit tests for the TypeScript function below. Cover: happy path, edge cases (empty input, null, very large values), and error handling. Use describe/it blocks, meaningful test names in English and no mocks unless necessary.
