insert into public.prompts (id, author_id, title, description, prompt_text, tool, content_type, status, origin_type, request_id, created_at, updated_at) values ('5eed0001-0000-4000-8000-000000000013', '5eed0000-0000-4000-8000-000000000005', 'Haiku Atölyesi Promptu', 'Öğrencilerime haiku yapısını öğretirken kullandığım prompt. 5-7-5 kuralını açıklatıyor.', 'Sen bir şiir öğretmenisin. Bana {mevsim} mevsimiyle ilgili 3 Türkçe haiku yaz. Her birinde 5-7-5 hece yapısını koru ve her haikudan sonra hecelerini parantez içinde say. Son olarak hangisinin neden en güçlü olduğunu tek cümleyle açıkla.', 'ChatGPT', 'text', 'published', 'original', null, '2026-08-14T00:50:14.185Z', '2026-08-14T00:50:14.185Z');
